{!! '<?php' !!}
/**
 * Generated by the control panel — do not edit by hand. Rewritten every time
 * someone opens a database here from the panel.
 *
 * Adminer's login form normally takes any server name and any driver: on a
 * public URL that is a tool for probing whatever this server can reach on the
 * network, and for opening SQLite files by path. This wrapper narrows it to
 * the panel's own database servers on this machine, picked from a list.
 *
 * Adminer itself is `adminer.php` beside this file, unmodified, so an update
 * replaces that file and leaves this one alone.
 */

const PANEL_SERVERS = {!! var_export($servers, true) !!};

/*
 * A login form names a server from the list; the driver comes from the list,
 * never from the form, so a crafted post cannot pair a listed server with a
 * driver it does not run (the shape of Adminer's own login-servers plugin).
 */
if (isset($_POST['auth']) && is_array($_POST['auth'])) {
    $panelServer = PANEL_SERVERS[(string) ($_POST['auth']['server'] ?? '')] ?? null;
    $_POST['auth']['driver'] = $panelServer['driver'] ?? '';
}

/*
 * Overrides are declared without types: the released single-file build has
 * its type declarations stripped, and a typed parameter in a child of an
 * untyped method is a fatal "must be compatible" error.
 */
function adminer_object()
{
    return new class extends \Adminer\Adminer
    {
        /** @return array{driver: string, host: string, label: string}|null */
        private function panelServer(): ?array
        {
            $server = PANEL_SERVERS[\Adminer\SERVER] ?? null;

            return $server !== null && $server['driver'] === \Adminer\DRIVER ? $server : null;
        }

        /*
         * The host always comes from the list. Anything not on it connects to
         * nothing in particular and is then refused by login() below — Adminer
         * connects before it asks login(), so the address must already be safe
         * by the time it does.
         */
        public function credentials()
        {
            return [$this->panelServer()['host'] ?? '127.0.0.1:1', $_GET['username'], \Adminer\get_password()];
        }

        public function login($login, $password)
        {
            if ($this->panelServer() === null) {
                return 'This Adminer opens only the databases on this server.';
            }

            return parent::login($login, $password);
        }

        public function loginFormField($name, $heading, $value)
        {
            if ($name === 'driver') {
                return '';
            }

            if ($name === 'server') {
                return $heading.\Adminer\html_select(
                    'auth[server]',
                    array_map(fn (array $server): string => $server['label'], PANEL_SERVERS),
                    \Adminer\SERVER,
                )."\n";
            }

            return parent::loginFormField($name, $heading, $value);
        }

        /* No call home to adminer.org from a customer's server. Updates come through the panel. */
        public function verifyVersion()
        {
            return false;
        }
    };
}

include __DIR__.'/adminer.php';
